function wizardActionLabel(button){return (button.getAttribute('aria-label')||button.textContent||'Action').replace(/\s+/gu,' ').trim()}
function wizardActionButton(event){
  const button=event.target?.closest?.('button');
  if(!button||button.disabled||button.matches('.nav,.theme-toggle,.clamp-toggle,[data-addon-sections],[data-clamp-toggle],[data-select-alert],[data-select-rule],[data-select-timer],[data-feedback-skip]'))return;
  const action={button,label:wizardActionLabel(button),at:Date.now(),feedbackSequence:wizardFeedbackSequence};
  pendingWizardAction=action;
  // API-backed handlers consume this action synchronously and replace this prompt with a
  // progress/result message. Local-only controls still receive visible confirmation instead
  // of appearing to do nothing.
  queueMicrotask(()=>{
    if(pendingWizardAction!==action)return;
    pendingWizardAction=undefined;
    if(wizardFeedbackSequence===action.feedbackSequence)showWizardFeedback(`${action.label} applied in this page.`,'success',button);
  });
}
