function timedMessagesFromSelection(selection){if(selection?.mode==='shuffle-container')return [...selection.messages];if(selection?.mode!=='platform-shuffle')return[];const seen=new Set();const merged=[];for(const platform of Object.keys(timedPlatformLimits))for(const message of selection.messagesByPlatform?.[platform]||[]){const normalized=String(message).trim();const key=normalized.toLocaleLowerCase();if(normalized&&!seen.has(key)){seen.add(key);merged.push(normalized)}}return merged}
