function renderCommandDirectoryPublication(publishing){const publicUrl=publishing?.publicUrl||'';byId('command-directory-public-url').value=publicUrl||'Not configured';byId('copy-public-command-directory').disabled=!publicUrl;byId('remove-public-command-directory').disabled=!publishing?.enabled;byId('publish-command-directory').disabled=!publishing?.enabled;return publishing?.enabled?(publishing.state==='ready'?'Hosted publishing is configured and will run at startup.':`Hosted publishing status: ${publishing.state}${publishing.error?` — ${publishing.error}`:''}`):'Hosted publishing is not configured. The local preview and static export remain available.'}
function filterCommandDirectory(){const query=byId('command-directory-search').value.trim().toLowerCase();const catalog=byId('command-directory-catalog');if(!catalog)return;let visibleCommands=0;for(const category of catalog.querySelectorAll(':scope>details')){let categoryMatches=0;for(const command of category.querySelectorAll('.command-center-list article')){const matches=!query||(command.dataset.search||'').includes(query);command.hidden=!matches;if(matches)categoryMatches+=1}category.hidden=categoryMatches===0;if(query&&categoryMatches>0)category.open=true;visibleCommands+=categoryMatches}const summary=byId('command-directory-summary');if(query)summary.innerHTML=`Showing <strong>${safe(visibleCommands)} matching command(s)</strong>.`;else if(summary.dataset.defaultSummary)summary.innerHTML=summary.dataset.defaultSummary}
