async function loadCommandDirectory(){const status=byId('command-directory-state');try{const catalogue=await api('/wizard/api/commands/directory');const summary=byId('command-directory-summary');summary.dataset.defaultSummary=`<strong>${safe(catalogue.commandCount)} public command(s)</strong> in ${safe(catalogue.categories.length)} categor${catalogue.categories.length===1?'y':'ies'}.`;summary.innerHTML=summary.dataset.defaultSummary;const catalog=byId('command-directory-catalog');if(catalog)catalog.innerHTML=catalogue.categories.length?catalogue.categories.map((category)=>`<details><summary><span><strong>${safe(category.name)}</strong><small>${safe(category.commands.length)} command(s)</small></span></summary><div class="command-center-list">${category.commands.map((command)=>{const fullCommand=catalogue.prefix+command.command;const platforms=command.platforms.map((platform)=>platformLabels[platform]||platform);const search=[fullCommand,command.description,category.name,...platforms].join(' ').toLowerCase();return`<article data-search="${safe(search)}"><code title="${safe(fullCommand)}">${safe(fullCommand)}</code><span class="command-center-description" title="${safe(command.description)}">${safe(command.description)}</span><span class="command-center-platforms" aria-label="Available on ${safe(platforms.join(', '))}">${platforms.map((platform)=>`<small class="command-platform-badge">${safe(platform)}</small>`).join('')}</span></article>`}).join('')}</div></details>`).join(''):'<p class="notice">No public viewer commands are enabled. Enable an add-on that provides commands, then restart the bridge.</p>';restoreDisclosureStates(catalog);filterCommandDirectory();status.textContent=`Active catalogue refreshed. Creator-only and moderation commands are hidden automatically. ${renderCommandDirectoryPublication(catalogue.publishing)}`}catch(error){status.textContent=`Command directory unavailable: ${error.message}`}}
function commandCatalogueMarkup(catalogue){return catalogue.categories.length?catalogue.categories.map((category)=>`<details><summary><span><strong>${safe(category.name)}</strong><small>${safe(category.commands.length)} command(s)</small></span></summary><div class="command-center-list">${category.commands.map((command)=>{const fullCommand=catalogue.prefix+command.command;const platforms=command.platforms.map((platform)=>platformLabels[platform]||platform);return`<article><code title="${safe(fullCommand)}">${safe(fullCommand)}</code><span class="command-center-description" title="${safe(command.description)}">${safe(command.description)}</span><span class="command-center-platforms" aria-label="Available on ${safe(platforms.join(', '))}">${platforms.map((platform)=>`<small class="command-platform-badge">${safe(platform)}</small>`).join('')}</span></article>`}).join('')}</div></details>`).join(''):'<p class="notice">No restricted commands are currently registered.</p>'}
