async function cancelConfigurationDraft(button){
  if(!state.draft||configurationOperationBusy())return;let message='';button.disabled=true;setConfigurationFinalizeOperation('discarding');renderDraft();
  try{state.draft=await api(`/wizard/api/transactions/${state.draft.id}/cancel`,{method:'POST'});state.overview=await api('/wizard/api/overview');state.draft=null;draftOutcome=null;renderOverview();message='Draft cancelled; no configuration was changed.';showWizardFeedback('Pending changes discarded. No saved setting changed.','success',button)}
  catch(error){message=error.message;showWizardFeedback(error.message,'error',button)}
  finally{setConfigurationFinalizeOperation();button.disabled=false;renderDraft(message)}
}
async function commitConfigurationDraft(button){
  if(!state.draft||configurationOperationBusy())return;let message='';button.disabled=true;setConfigurationFinalizeOperation('saving');renderDraft();
  try{const committed=await api(`/wizard/api/transactions/${state.draft.id}/commit`,{method:'POST'});state.draft=null;state.overview=await api('/wizard/api/overview');const restartRequired=committed.restartRequired!==false||state.overview.configuration.activation?.restartRequired===true;draftOutcome={kind:'committed',backupPath:committed.backupPath,restartRequired};renderOverview();await loadConnectionCenter();message=restartRequired?'Saved with a local backup. Restart StreamBridge to apply the settings.':'Saved with a local backup. The active configuration already matches; no restart is needed.';showWizardFeedback(message,'success',button)}
  catch(error){message=error.message;showWizardFeedback(error.message,'error',button)}
  finally{setConfigurationFinalizeOperation();button.disabled=false;renderDraft(message)}
}
async function restartStreamBridge(button){button.disabled=true;showWizardFeedback('Checking that every platform is offline before restarting StreamBridge…','busy',button);try{const result=await api('/wizard/api/restart',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({approvedByCreator:true})});const bar=byId('global-change-bar');bar.dataset.state='restarting';bar.innerHTML=`<div class="global-change-copy"><span class="status-chip status-neutral">Restarting</span><strong>Activating your saved settings</strong><small>${safe(result.message||'This tab may briefly disconnect. A fresh unlocked Wizard window will open automatically.')}</small></div><div class="global-change-actions"><button type="button" class="compact" disabled>Restart in progress…</button></div>`}catch(error){showWizardFeedback(error.message,'error',button);button.disabled=false}}
async function stagePlatform(event){try{const card=event.target.closest('[data-platform]');const values=Object.fromEntries([...card.querySelectorAll('input[data-flag]')].map((input)=>[input.dataset.flag,input.checked]));await stageConfigurationChange({kind:'platform',platform:card.dataset.platform,...values})}catch(error){showWizardFeedback(`Platform change was not staged: ${error.message}`,'error',event.target)}}
