const optionalStreamingAppLabels={obs:'OBS Studio',meld:'Meld Studio',streamlabs:'Streamlabs Desktop',speakerbot:'Speaker.bot'};
function optionalStreamingAppLabel(application){return optionalStreamingAppLabels[application]||application}
function startupReportText(report){if(!report?.message)return'';const run=typeof report.startupRunId==='string'?` · run ${report.startupRunId.slice(0,8)}`:'';if(report.outcome==='in-progress'){const phase=String(report.phase||'starting').replaceAll('-',' ');const attempt=Number(report.attempt)>0?` · attempt ${report.attempt}`:'';return` Startup progress: ${phase}${attempt}${run} — ${report.message}`}const parsed=new Date(report.timestamp);const when=Number.isNaN(parsed.getTime())?'recently':parsed.toLocaleString();const category=report.category&&report.category!=='none'?` [${report.category}]`:'';const blockers=Array.isArray(report.readinessBlockers)&&report.readinessBlockers.length?` Recovery: ${report.readinessBlockers.map((item)=>`${item.name}: ${item.recovery}`).join(' ')}`:'';return` Last startup (${when})${run}${category}: ${report.message}${blockers}`}
function renderStreamerBotLauncher(status){const badge=byId('streamerbot-launcher-badge');const input=byId('streamerbot-executable');const message=byId('streamerbot-launcher-state');badge.dataset.state=status.state;badge.textContent=({ready:'Ready',stopped:'Stopped','not-configured':'Setup needed',missing:'File missing','port-conflict':'Port conflict',unsupported:'Unavailable'})[status.state]||status.state;input.value=status.executable||'';byId('streambridge-install-path').value=status.installRoot||'';byId('streamdeck-launch-target').value=status.streamDeckTarget||'';byId('streamerbot-port').textContent=`WebSocket port ${status.websocketPort} · loaded from the active StreamBridge configuration.`;message.textContent=status.message+startupReportText(status.lastStartupReport);const launchDisabled=!status.configured||!status.executableExists||status.state==='port-conflict'||status.state==='unsupported';byId('start-streaming-tools').disabled=launchDisabled;byId('start-streamerbot-safe').disabled=launchDisabled;byId('create-streamerbot-shortcut').disabled=!status.configured||!status.executableExists||status.state==='unsupported';for(const application of Object.keys(optionalStreamingAppLabels)){const app=status.optionalApps?.[application]||{};byId(`optional-${application}-executable`).value=app.executable||'';const toggle=byId(`optional-${application}-enabled`);toggle.checked=app.enabled===true;toggle.disabled=!status.configured||!app.configured||app.state==='unsupported';byId(`optional-${application}-state`).textContent=app.message||'Optional app is not configured.'}}
async function loadStreamerBotLauncher(){try{renderStreamerBotLauncher(await api('/wizard/api/streamerbot-launcher'))}catch(error){byId('streamerbot-launcher-state').textContent=`Safe launcher unavailable: ${error.message}`}}
async function runWithStartupProgress(task,button){let active=true;const poll=(async()=>{while(active){await wait(500);if(!active)break;try{const status=await api('/wizard/api/streamerbot-launcher');renderStreamerBotLauncher(status);if(status.lastStartupReport?.outcome==='in-progress')showWizardFeedback(status.lastStartupReport.message,'busy',button)}catch{}}})();try{return await task()}finally{active=false;await poll}}
const connectionPlatformNames=new Set(['twitch','youtube','kick','tiktok','streamlabs','kofi']);
function setConnectionBadge(label,state){const badge=byId('connection-center-badge');badge.textContent=label;badge.classList.remove('status-ready','status-warning','status-neutral');badge.classList.add(state==='ready'?'status-ready':state==='warning'?'status-warning':'status-neutral')}
function renderConnectionCenterBase(result){const readiness=result?.readiness||{};const launcher=result?.launcher||{};const output=(readiness.outputs||[]).find((candidate)=>candidate.name==='streamerbot');const outputConnected=output?.state==='connected';const adapters=(readiness.adapters||[]).filter((candidate)=>connectionPlatformNames.has(candidate.name)&&candidate.state!=='disabled');const platformProblems=adapters.filter((candidate)=>candidate.state!=='connected');const modules=readiness.modules||[];const moduleProblems=modules.filter((candidate)=>candidate.status!=='healthy');const exactBlockers=Array.isArray(readiness.blockers)?readiness.blockers:[];byId('connection-bridge').textContent='Running';byId('connection-streamerbot').textContent=outputConnected?'Connected':launcher.state==='not-configured'?'Setup needed':launcher.state==='missing'?'File moved':launcher.state==='port-conflict'?'Port conflict':launcher.state==='unsupported'?'Manual start required':'Not connected';const port=launcher.websocketPort?` on port ${launcher.websocketPort}`:'';byId('connection-streamerbot-detail').textContent=outputConnected?'Bridge delivery is connected to Streamer.bot.':launcher.state==='not-configured'?'Choose Streamer.bot.exe once to enable safe recovery.':launcher.state==='missing'?'The saved Streamer.bot.exe location no longer exists.':launcher.state==='port-conflict'?`Another program owns the configured WebSocket port${port}. Nothing will be stopped automatically.`:launcher.state==='unsupported'?'Safe application startup is available on Windows only.':`Streamer.bot WebSocket delivery is not accepting connections${port}.`;byId('connection-platforms').textContent=adapters.length===0?'None enabled':platformProblems.length===0?`${adapters.length} connected`:`${adapters.length-platformProblems.length} of ${adapters.length} connected`;byId('connection-platforms-detail').textContent=adapters.length===0?'Choose at least one platform when you are ready.':platformProblems.length===0?`Ready: ${adapters.map((adapter)=>platformLabels[adapter.name]||adapter.name).join(', ')}.`:`Needs attention: ${platformProblems.map((adapter)=>platformLabels[adapter.name]||adapter.name).join(', ')}.`;byId('connection-modules').textContent=moduleProblems.length===0?`${modules.length} healthy`:`${moduleProblems.length} need attention`;byId('connection-modules-detail').textContent=moduleProblems.length===0?'All loaded feature modules passed their health check.':`Review: ${moduleProblems.map((module)=>module.moduleId).join(', ')}.`;const ready=readiness.ready===true;let summary;let detail;if(ready){summary='StreamBridge is ready for enabled platforms and Streamer.bot delivery.';detail=moduleProblems.length===0?'No connection recovery is required.':`${moduleProblems.length} optional feature module(s) need attention, but core readiness is not blocked.`;setConnectionBadge('Ready','ready')}else if(launcher.state==='not-configured'||launcher.state==='missing'){summary='StreamBridge is running, but Streamer.bot safe recovery needs setup.';detail=launcher.message||'Open connection settings and select Streamer.bot.exe.';setConnectionBadge('Setup required','warning')}else if(launcher.state==='port-conflict'){summary='StreamBridge is running, but another program owns the Streamer.bot WebSocket port.';detail=launcher.message||'Open connection settings and choose a different WebSocket port. The other program will not be stopped automatically.';setConnectionBadge('Port conflict','warning')}else if(!outputConnected){summary='StreamBridge is running, but Streamer.bot delivery is disconnected.';detail=launcher.state==='stopped'?'Start Streamer.bot safely, then test connections again.':'Confirm Streamer.bot is open and its WebSocket server has Auto Start enabled.';setConnectionBadge('Streamer.bot offline','warning')}else{summary='Core delivery is connected, but one or more enabled components need attention.';detail=exactBlockers.length?exactBlockers.map((blocker)=>`${blocker.name} is ${blocker.state}. ${blocker.recovery}`).join(' '):platformProblems.length?`Reconnect ${platformProblems.map((adapter)=>platformLabels[adapter.name]||adapter.name).join(', ')} in its provider, then test again.`:'Open Test & finish for the affected feature modules.';setConnectionBadge('Needs attention','warning')}byId('connection-center-summary').textContent=summary;byId('connection-center-detail').textContent=detail;const canStart=launcher.configured===true&&launcher.executableExists===true&&!['port-conflict','unsupported'].includes(launcher.state);byId('connection-start-streamerbot').classList.toggle('hidden',!canStart||outputConnected);byId('connection-start-all').classList.toggle('hidden',!canStart);if(outputConnected)setGuidedSetupStepComplete('streamerbot');if(adapters.length>0&&platformProblems.length===0)setGuidedSetupStepComplete('platforms')}
function renderReadinessActions(blockers=[]){const actions=byId('connection-center')?.querySelector('.connection-center-actions');if(!actions)return;actions.querySelectorAll('[data-readiness-action]').forEach((button)=>button.remove());const seen=new Set();for(const blocker of Array.isArray(blockers)?blockers:[]){const action=blocker?.action;if(!action||typeof action.type!=='string'||typeof action.label!=='string')continue;const key=`${action.type}:${action.target||''}`;if(seen.has(key))continue;seen.add(key);const button=document.createElement('button');button.type='button';button.className='ghost';button.dataset.readinessAction=action.type;button.dataset.readinessTarget=action.target||'';button.textContent=action.label;actions.insertBefore(button,byId('connection-open-settings'))}}
function renderConnectionCenter(result){renderConnectionCenterBase(result);renderReadinessActions(result?.readiness?.blockers);const activation=result?.configuration||state.overview?.configuration?.activation||{};const pending=activation.restartRequired===true;byId('connection-configuration').textContent=pending?'Restart needed':activation.state==='unavailable'?'Unavailable':'Active';byId('connection-configuration-detail').textContent=pending?'Saved settings are waiting for an offline restart.':activation.state==='unavailable'?'This installation does not expose configuration activation status.':`This process loaded the current saved settings${activation.activatedAt?` at ${new Date(activation.activatedAt).toLocaleTimeString()}`:''}.`;if(pending){byId('connection-center-summary').textContent='Saved settings are waiting to be activated.';byId('connection-center-detail').textContent='Finish any live stream, then use Restart safely. Your current session continues with its previously loaded settings.';setConnectionBadge('Restart needed','warning')}}
async function loadConnectionCenter(){const retry=byId('connection-retry');retry.disabled=true;byId('connection-center-detail').textContent='Testing local connections…';try{renderConnectionCenter(await api('/wizard/api/readiness'))}catch(error){setConnectionBadge('Check failed','warning');byId('connection-center-summary').textContent='StreamBridge is open, but the readiness details could not be loaded.';byId('connection-center-detail').textContent=`Connection check failed: ${error.message}`}finally{retry.disabled=false}}
function readPreflightConfirmation(){try{return JSON.parse(localStorage.getItem(PREFLIGHT_STORAGE_KEY)||'{}')?.importConfirmed===true}catch{return false}}
function savePreflightConfirmation(importConfirmed){try{localStorage.setItem(PREFLIGHT_STORAGE_KEY,JSON.stringify({importConfirmed}));return true}catch{return false}}
function renderPreflightCard({title,ready,detail,target,optional=false}){const label=optional?'Optional':ready?'Ready':'Needs attention';const tone=optional?'status-neutral':ready?'status-ready':'status-warning';return `<article class="pre-stream-card ${ready?'is-ready':'needs-attention'} ${optional?'is-optional':''}"><div><span class="status-chip ${tone}">${label}</span><h4>${safe(title)}</h4><p>${safe(detail)}</p></div>${target?`<button type="button" class="ghost compact" data-preflight-target="${safe(target)}">Open setup</button>`:''}</article>`}
function renderPreStreamReadiness(result=state.preflightReadiness,inspection=state.lastInspection){
  const target=byId('pre-stream-grid');if(!target)return;
  const readiness=result?.readiness||{};const output=(readiness.outputs||[]).find((candidate)=>candidate.name==='streamerbot');const streamerBotReady=output?.state==='connected';
  const adapters=(readiness.adapters||[]).filter((candidate)=>connectionPlatformNames.has(candidate.name)&&candidate.state!=='disabled');const platformProblems=adapters.filter((candidate)=>candidate.state!=='connected');const platformsReady=adapters.length>0&&platformProblems.length===0;
  const modules=readiness.modules||[];const moduleProblems=modules.filter((candidate)=>candidate.status!=='healthy');const modulesReady=modules.length>0&&moduleProblems.length===0;
  const inspectionRequests=Array.isArray(inspection?.requests)?inspection.requests:[];const inspectionReady=inspection?.available===true&&inspectionRequests.length>0;const importConfirmed=readPreflightConfirmation();const bridgeReady=Boolean(result);byId('pre-stream-import-confirmed').checked=importConfirmed;
  const overlaySetup=readOverlaySetupState();const overlaySources=overlaySourceCatalog();const overlayChecked=overlaySources.filter((source)=>overlaySetup.verified[source.id]===true).length;const obsVisibility=result?.overlay?.hostVisibility;const obsSources=Array.isArray(obsVisibility?.obsSources)?obsVisibility.obsSources:[];const visibleObsSources=obsSources.filter((source)=>source.visible===true).length;
  const inventory=result?.obsInventory||{};const expectedObsSources=Array.isArray(inventory.sources)?inventory.sources:[];
  const checks=[
    {title:'StreamBridge service',ready:bridgeReady,detail:bridgeReady?'The local Bridge and setup wizard are responding.':'Restart StreamBridge from the tray or installed launcher.',target:'overview'},
    {title:'Streamer.bot delivery',ready:streamerBotReady,detail:streamerBotReady?'Read-only and delivery connections are active.':'Open Streamer.bot and enable its WebSocket server Auto Start.',target:'streamerbot'},
    {title:'Enabled platforms',ready:platformsReady,detail:adapters.length===0?'Choose at least one platform.':platformsReady?`${adapters.length} enabled platform${adapters.length===1?' is':'s are'} connected.`:`Reconnect: ${platformProblems.map((adapter)=>platformLabels[adapter.name]||adapter.name).join(', ')}.`,target:'platforms'},
    {title:'Included features',ready:modulesReady,detail:modulesReady?`${modules.length} loaded feature modules are healthy.`:moduleProblems.length?`Review: ${moduleProblems.map((module)=>module.moduleId).join(', ')}.`:'Feature health was not reported.',target:'addons'},
    {title:'Streamer.bot inspection',ready:inspectionReady,detail:inspectionReady?`${inspectionRequests.length} read-only inspection request${inspectionRequests.length===1?'':'s'} completed.`:inspection?.available===true?'No audited read response was returned. Reconnect Streamer.bot, then run this check again.':'Reconnect Streamer.bot, then run this check again.',target:'streamerbot'},
    {title:'Import and triggers confirmed',ready:importConfirmed,detail:importConfirmed?'You confirmed the current package and recommended triggers.':'Import the one Wizard-generated package, attach its checklist triggers, then confirm below.',target:'streamerbot'},
    ...(inventory.configured===true?[{title:'Expected OBS scene sources',ready:inventory.ready===true,detail:inventory.ready===true?`${inventory.readyRequiredCount} required source expectation${inventory.readyRequiredCount===1?' is':'s are'} visible in the exact program scene.`:`${inventory.readyRequiredCount||0} of ${inventory.requiredCount||0} required expectations are visible. Missing: ${expectedObsSources.filter((source)=>source.required&&!source.ready).map((source)=>`${source.label} in ${source.scene}`).join(', ')||'open OBS and the expected scenes'}.`,target:'diagnostics'}]:[]),
  ];
  target.innerHTML=checks.map(renderPreflightCard).join('')+renderPreflightCard({title:'On-stream overlays',ready:overlaySources.length>0&&overlayChecked===overlaySources.length,detail:overlaySources.length?`${overlayChecked} of ${overlaySources.length} current source${overlaySources.length===1?'':'s'} checked in your streaming app.`:'Overlays are not required for chat delivery or commands.',target:'chat-overlay',optional:true})+renderPreflightCard({title:'OBS source visibility',ready:visibleObsSources>0,detail:obsVisibility?.supported===true?`${visibleObsSources} of ${obsSources.length} connected OBS browser source${obsSources.length===1?' is':'s are'} currently visible. This is a read-only signal from OBS.`:'No OBS browser-source visibility signal is available. Open an installed StreamBridge overlay in OBS to enable this optional check.',target:'chat-overlay',optional:true});
  target.querySelectorAll('[data-preflight-target]').forEach((button)=>button.addEventListener('click',()=>document.querySelector(`[data-view="${CSS.escape(button.dataset.preflightTarget)}"]`)?.click()));
  const remaining=checks.filter((check)=>!check.ready).length;const badge=byId('pre-stream-badge');badge.textContent=remaining===0?'Ready to stream':`${remaining} step${remaining===1?'':'s'} left`;badge.className=`status-chip ${remaining===0?'status-ready':'status-warning'}`;
  byId('pre-stream-summary').textContent=remaining===0?'All required local checks passed. Optional overlays can be completed whenever you use them.':`Complete ${remaining} required item${remaining===1?'':'s'} below, then run the check again.`;
  byId('pre-stream-state').textContent=inspection?.available===false?`Streamer.bot inspection is unavailable: ${inspection.error||'confirm its WebSocket server is connected.'}`:'No live platform action was performed.';
  if(remaining===0)setGuidedSetupStepComplete('test');
}
async function loadPreStreamReadiness(){const button=byId('refresh-preflight');button.disabled=true;byId('pre-stream-state').textContent='Running local health and read-only Streamer.bot checks…';try{const [readiness,inspection]=await Promise.all([api('/wizard/api/readiness'),inspectStreamerBot()]);state.preflightReadiness=readiness;state.lastInspection=inspection;state.obsInventory=readiness.obsInventory;renderBuildProvenance(readiness.provenance);renderObsInventory(readiness.obsInventory);renderConnectionCenter(readiness);renderPreStreamReadiness(readiness,inspection);showWizardFeedback('Pre-stream check completed.','success',button)}catch(error){renderPreStreamReadiness();byId('pre-stream-state').textContent=`Pre-stream check could not finish: ${error.message}`;showWizardFeedback(error.message,'error',button)}finally{button.disabled=false}}
function renderBuildProvenance(provenance){const verified=provenance?.installation==='verified-portable-release';const badge=byId('build-provenance-badge');badge.textContent=verified?'Verified portable build':'Local development build';badge.className=`status-chip ${verified?'status-ready':'status-warning'}`;const short=(value)=>typeof value==='string'?value.slice(0,16):'Unavailable';byId('build-provenance-details').innerHTML=`<div><dt>Version</dt><dd>${safe(provenance?.version||'Unknown')}</dd></div><div><dt>Build fingerprint</dt><dd><code>${safe(short(provenance?.buildFingerprint))}</code></dd></div><div><dt>Manifest SHA-256</dt><dd><code>${safe(short(provenance?.releaseManifestSha256))}</code></dd></div><div><dt>Runtime</dt><dd>${safe(provenance?.runtimeVersion||'Development runtime')}</dd></div><div><dt>Installed</dt><dd>${safe(provenance?.installedAt?new Date(provenance.installedAt).toLocaleString():'Not installed from a portable release')}</dd></div>`}
function obsInventoryId(label,scene,surface){return `${String(label).toLowerCase().replace(/[^a-z0-9]+/gu,'-').replace(/^-|-$/gu,'').slice(0,48)||'source'}-${String(scene+surface).split('').reduce((hash,char)=>((hash*31)+char.charCodeAt(0))>>>0,0).toString(36)}`.slice(0,80)}
function renderObsInventory(result=state.obsInventory){state.obsInventory=result||{sources:[],discovered:[],reconciliations:[]};const sources=Array.isArray(state.obsInventory.sources)?state.obsInventory.sources:[];const discovered=Array.isArray(state.obsInventory.discovered)?state.obsInventory.discovered:[];const reconciliations=Array.isArray(state.obsInventory.reconciliations)?state.obsInventory.reconciliations:[];const target=byId('obs-inventory-list');target.innerHTML=sources.length?sources.map((source)=>{const reconciliation=reconciliations.find((item)=>item.sourceId===source.id);return`<article class="item"><div><span class="status-chip ${source.ready?'status-ready':'status-warning'}">${source.ready?'Visible':'Missing'}</span><strong>${safe(source.label)}</strong><p>${safe(source.scene)} · <code>${safe(source.surface)}</code>${source.moduleId?` · ${safe(source.moduleId)}`:''}</p><small>${source.visibleCount||0} visible of ${source.minimumCount} required.</small>${reconciliation?`<p class="notice">${safe(reconciliation.reason)}</p>`:''}</div><div class="button-row">${reconciliation?`<button type="button" class="ghost compact" data-reconcile-obs-source="${safe(source.id)}">Use detected replacement</button>`:''}<button type="button" class="danger compact" data-remove-obs-source="${safe(source.id)}">Remove</button></div></article>`}).join(''):'<p class="notice">No expected OBS sources configured. Add the exact sources you rely on for each program scene.</p>';byId('obs-discovered-list').innerHTML=discovered.length?discovered.map((source,index)=>`<article class="item"><div><span class="status-chip ${source.visibleCount?'status-ready':'status-neutral'}">Detected</span><strong>${safe(source.suggestedLabel)}</strong><p>${safe(source.scene)} · <code>${safe(source.surface)}</code>${source.moduleId?` · ${safe(source.moduleId)}`:''}</p><small>${source.visibleCount||0} visible · ${source.connectedCount||0} connected.</small></div><button type="button" class="ghost compact" data-use-obs-source="${index}">Use detected source</button></article>`).join(''):'<p class="notice">No unsaved StreamBridge sources are currently detected in an OBS program scene.</p>';byId('obs-inventory-state').textContent=sources.length?`${state.obsInventory.readyRequiredCount||0} of ${state.obsInventory.requiredCount||0} required source expectations are currently visible${reconciliations.length?` · ${reconciliations.length} replacement suggestion${reconciliations.length===1?'':'s'} available`:''}.`:'Inventory is optional until you add a required source.'}
async function saveObsInventory(sources){state.obsInventory=await api('/wizard/api/obs-source-inventory',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({sources,approvedByCreator:true})});renderObsInventory();if(state.preflightReadiness){state.preflightReadiness={...state.preflightReadiness,obsInventory:state.obsInventory};renderPreStreamReadiness()}}
async function loadObsInventory(){try{renderObsInventory(await api('/wizard/api/obs-source-inventory'))}catch(error){byId('obs-inventory-state').textContent=`Expected OBS inventory could not load: ${error.message}`}}
function matchingAcceptanceEvidence(check,evidence){return evidence.filter((item)=>(!Array.isArray(check.platforms)||check.platforms.includes(item.platform))&&(!Array.isArray(check.eventTypes)||check.eventTypes.includes(item.eventType)))}
function renderLiveAcceptance(result=state.liveAcceptance){const target=byId('live-acceptance-list');if(!target)return;const checks=Array.isArray(result?.checks)?result.checks:[];const evidence=Array.isArray(result?.evidence)?result.evidence:[];const confirmations=result?.confirmations||{};if(!checks.length){target.innerHTML='<p class="notice">Live acceptance tracking is unavailable.</p>';return}target.innerHTML=checks.map((check)=>{const saved=confirmations[check.id]||{};const stale=saved.status==='stale';const due=saved.status==='due';const dueSoon=saved.dueSoon===true;const accepted=saved.status==='accepted';const matches=matchingAcceptanceEvidence(check,evidence);const reasons=Array.isArray(saved.staleReasons)?saved.staleReasons:[saved.staleReason||saved.dueReason||saved.dueSoonReason].filter(Boolean);const options=matches.map((item)=>`<option value="${safe(item.id)}" ${saved.evidenceId===item.id?'selected':''}>${safe(item.platform)} · ${safe(item.eventType)} · ${safe(item.upstreamEventId)} · ${safe(new Date(item.receivedAt).toLocaleString())}</option>`).join('');return `<form class="item live-acceptance-item" data-live-acceptance-id="${safe(check.id)}"><div><span class="status-chip ${accepted&&!dueSoon?'status-ready':stale||due||dueSoon?'status-warning':'status-neutral'}">${stale?'Changed · recheck':due?'Periodic recheck due':dueSoon?'Recheck due soon':accepted?'Accepted':'Pending'}</span><strong>${safe(check.label)}</strong><p>${safe(check.guidance)}</p>${stale||due||dueSoon?`<ul>${reasons.map((reason)=>`<li>${safe(reason)}</li>`).join('')}</ul>`:''}${saved.dueAt?`<small>${due?'Due':dueSoon?'Due soon':'Next periodic recheck'}: ${safe(new Date(saved.dueAt).toLocaleDateString())} · every ${safe(check.recheckAfterDays)} days</small>`:''}</div><label>Status<select name="status"><option value="pending" ${!accepted?'selected':''}>Pending</option><option value="accepted" ${accepted?'selected':''}>Accepted</option></select></label>${check.requiresGenuineEvent?`<label>Captured genuine event<select name="evidenceId"><option value="">Choose genuine evidence</option>${options}</select><small>${matches.length?`${matches.length} matching event(s) captured without chat text or viewer identity.`:'No matching genuine event captured yet.'}</small></label>`:''}<label>Creator result note<input name="note" maxlength="300" value="${safe(saved.note||'')}" placeholder="What you observed end to end"></label><label class="check"><input name="approvedByCreator" type="checkbox" required> I personally verified this result against the current build</label><button type="submit">Save acceptance</button></form>`}).join('')}
async function loadLiveAcceptance(){const button=byId('refresh-live-acceptance');if(button)button.disabled=true;byId('live-acceptance-state').textContent='Loading genuine event evidence…';try{state.liveAcceptance=await api('/wizard/api/live-acceptance');renderLiveAcceptance();const captured=Array.isArray(state.liveAcceptance.evidence)?state.liveAcceptance.evidence.length:0;byId('live-acceptance-state').textContent=`${captured} recent genuine upstream event(s) available for creator review.`}catch(error){byId('live-acceptance-state').textContent=`Live acceptance could not load: ${error.message}`}finally{if(button)button.disabled=false}}
async function downloadSupportBundle(button){button.disabled=true;showWizardFeedback('Downloading the exact reviewed support snapshot…','busy',button);try{if(!state.supportBundlePreview?.previewId)throw new Error('Preview the support bundle in this tab first.');const response=await fetch('/wizard/api/support-bundle',{headers:{authorization:`Bearer ${state.token}`,'x-thsv-wizard-tab':wizardTabId,'x-thsv-support-preview':state.supportBundlePreview.previewId}});if(!response.ok){let message=`Support bundle failed (${response.status})`;try{message=(await response.json()).error||message}catch{}throw new Error(message)}const blob=await response.blob();const disposition=response.headers.get('content-disposition')||'';const filename=/filename="([^"]+)"/u.exec(disposition)?.[1]||'THSV-StreamBridge-support.zip';const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);state.supportBundlePreview=null;showWizardFeedback('The exact reviewed support snapshot downloaded. Preview again before another download.','success',button)}catch(error){showWizardFeedback(error.message,'error',button)}finally{button.disabled=!state.supportBundlePreview}}
async function previewSupportBundle(button){button.disabled=true;showWizardFeedback('Building an exact sanitized snapshot for review…','busy',button);try{const preview=await api('/wizard/api/support-bundle/preview');state.supportBundlePreview=preview;byId('support-bundle-preview').innerHTML=`<article class="item"><div><strong>${safe(preview.filename)}</strong><p>${preview.files.length} files · ${preview.archiveBytes} archive bytes · ${preview.totalRedactions} redaction${preview.totalRedactions===1?'':'s'}</p><small>SHA-256 ${safe(preview.sha256)} · expires ${safe(new Date(preview.expiresAt).toLocaleTimeString())}. Always omitted: ${safe(preview.omittedCategories.join(', '))}.</small></div></article>${preview.files.map((file)=>`<article class="item"><div><strong><code>${safe(file.path)}</code></strong><small>${file.bytes} bytes${file.truncated?` · truncated from ${file.sourceBytes}`:''} · ${file.redactions} redaction${file.redactions===1?'':'s'}</small></div></article>`).join('')}`;byId('download-support-bundle').disabled=false;showWizardFeedback('This exact byte snapshot is ready. Review it, then download within five minutes.','success',button)}catch(error){state.supportBundlePreview=null;byId('download-support-bundle').disabled=true;showWizardFeedback(error.message,'error',button)}finally{button.disabled=false}}
function loadPreStreamHistory(){try{const value=JSON.parse(localStorage.getItem(PRE_STREAM_HISTORY_KEY)||'[]');return Array.isArray(value)?value.filter((item)=>item?.report?.schemaVersion===1&&typeof item.savedAt==='string').slice(0,PRE_STREAM_HISTORY_LIMIT):[]}catch{return []}}
function savePreStreamHistory(items){try{localStorage.setItem(PRE_STREAM_HISTORY_KEY,JSON.stringify(items.slice(0,PRE_STREAM_HISTORY_LIMIT)));return true}catch{return false}}
function renderPreStreamHistory(){const target=byId('pre-stream-history');if(!target)return;const enabled=byId('keep-pre-stream-history').checked;const items=loadPreStreamHistory();byId('clear-pre-stream-history').disabled=items.length===0;if(!enabled&&items.length===0){target.innerHTML='<p class="notice">Local report history is off.</p>';return}if(items.length===0){target.innerHTML='<p class="notice">No sanitized reports have been saved in this browser yet.</p>';return}target.innerHTML=items.map((item,index)=>`<article class="item"><div><strong>${safe(item.report?.build?.version?`StreamBridge ${item.report.build.version}`:'Pre-stream report')}</strong><small>${safe(new Date(item.savedAt).toLocaleString())} · ${safe(item.report?.readiness?.ready?'Ready':'Needs attention')}</small></div><button type="button" class="ghost compact" data-compare-history="${index}">Compare now</button></article>`).join('')}
function rememberPreStreamReport(report){if(!byId('keep-pre-stream-history').checked)return;const items=loadPreStreamHistory();items.unshift({savedAt:new Date().toISOString(),report});if(!savePreStreamHistory(items))throw new Error('The report downloaded, but browser history storage is unavailable.');renderPreStreamHistory()}
async function exportPreStreamReport(button){button.disabled=true;showWizardFeedback('Creating a sanitized pre-stream report…','busy',button);try{const response=await fetch('/wizard/api/pre-stream-report',{headers:{authorization:`Bearer ${state.token}`,'x-thsv-wizard-tab':wizardTabId}});if(!response.ok)throw new Error((await response.json()).error||`Pre-stream report failed (${response.status})`);const bytes=await response.arrayBuffer();const text=new TextDecoder().decode(bytes);rememberPreStreamReport(JSON.parse(text));const blob=new Blob([bytes],{type:'application/json'});const filename=/filename="([^"]+)"/u.exec(response.headers.get('content-disposition')||'')?.[1]||'THSV-StreamBridge-pre-stream.json';const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);showWizardFeedback(`Sanitized pre-stream report exported${byId('keep-pre-stream-history').checked?' and saved locally':''}.`,'success',button)}catch(error){showWizardFeedback(error.message,'error',button)}finally{button.disabled=false}}
async function comparePreStreamBaseline(baseline,label,button,stored=false){button.disabled=true;showWizardFeedback('Comparing the earlier report with the current installed state…','busy',button);try{const comparison=await api('/wizard/api/pre-stream-report/compare',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({baseline})});const changes=Array.isArray(comparison.changes)?comparison.changes:[];byId('pre-stream-comparison').innerHTML=`<article class="item"><div><span class="status-chip ${comparison.regressions?'status-warning':comparison.changed?'status-neutral':'status-ready'}">${comparison.regressions?`${comparison.regressions} regression${comparison.regressions===1?'':'s'}`:comparison.changed?'Changed':'No changes'}</span><strong>${safe(comparison.summary)}</strong><small>${safe(label)} compared with the current installed state. ${stored?'The baseline remains in optional local browser history.':'The selected file was not stored.'}</small></div></article>${changes.map((change)=>`<article class="item"><div><span class="status-chip ${change.severity==='regression'?'status-warning':change.severity==='improvement'?'status-ready':'status-neutral'}">${safe(change.severity)}</span><strong>${safe(change.label)}</strong><small>${safe(change.before)} → ${safe(change.after)}</small></div></article>`).join('')}`;showWizardFeedback('Pre-stream report comparison completed.','success',button)}catch(error){showWizardFeedback(error.message,'error',button)}finally{button.disabled=false}}
async function comparePreStreamReport(file,button){try{if(file.size>512*1024)throw new Error('The selected report exceeds 512 KB.');await comparePreStreamBaseline(JSON.parse(await file.text()),file.name,button)}catch(error){showWizardFeedback(error.message,'error',button);button.disabled=false}}
function selectedUniversalImportFolders(){return [...document.querySelectorAll('#universal-import-packages input[data-import-folder]:checked')].map((input)=>input.dataset.importFolder)}
function updateUniversalImportSummary(){const selected=new Set(selectedUniversalImportFolders());const packages=state.universalImports?.packages||[];const chosen=packages.filter((item)=>selected.has(item.folder));const actions=chosen.reduce((total,item)=>total+item.actionCount,0);const commands=chosen.reduce((total,item)=>total+item.commandCount,0);byId('universal-import-summary').textContent=`${chosen.length} packages · ${actions} actions${commands?` · ${commands} commands`:''}`;byId('download-universal-import').disabled=chosen.length===0;byId('show-trigger-guide').disabled=!state.lastUniversalImport}
function renderUniversalImportCatalogue(catalogue){state.universalImports=catalogue;state.lastUniversalImport=null;const groups=[['core','Always included','Connection, receiver, delivery, administration, and setup actions required by StreamBridge.'],['extension','Included features','Built-in StreamBridge features. Choose only what you plan to use.'],['addon','Installed optional add-ons','Optional package actions become selectable after their matching add-on is installed.']];const target=byId('universal-import-packages');target.innerHTML=groups.map(([kind,title,description])=>{const packages=catalogue.packages.filter((item)=>item.kind===kind);if(!packages.length)return'';return`<section class="universal-import-group" data-import-kind="${safe(kind)}"><header><div><h4>${safe(title)}</h4><p>${safe(description)}</p></div><small>${safe(packages.length)} package(s)</small></header><div class="universal-import-options">${packages.map((item)=>`<label class="universal-import-option"><input type="checkbox" data-import-folder="${safe(item.folder)}" ${item.required||item.enabled&&item.available?'checked':''} ${item.required||!item.available?'disabled':''}><span class="universal-import-option-copy"><strong>${safe(item.name.replace(/^THSV StreamBridge - /u,''))}</strong><small>${safe(item.description||'Reviewed StreamBridge action package.')}${!item.available?' Install and enable the matching add-on first.':''}</small></span><span class="universal-import-option-meta">${safe(item.actionCount)} action${item.actionCount===1?'':'s'}</span></label>`).join('')}</div></section>`}).join('');target.querySelectorAll('input[data-import-folder]').forEach((input)=>input.addEventListener('change',()=>{state.lastUniversalImport=null;byId('universal-trigger-list').innerHTML='<p class="notice">Generate the updated import to create its exact trigger checklist.</p>';updateUniversalImportSummary()}));byId('universal-import-badge').textContent=`v${catalogue.bridgeVersion}`;byId('universal-import-state').textContent=`Ready for Streamer.bot ${catalogue.minimumStreamerBotVersion} or newer. Select features, then create one import.`;updateUniversalImportSummary()}
async function loadUniversalImportCatalogue(){const status=byId('universal-import-state');try{renderUniversalImportCatalogue(await api('/wizard/api/streamerbot/import-catalogue'))}catch(error){byId('universal-import-badge').textContent='Unavailable';status.textContent=`Universal import unavailable: ${error.message}`}}
function renderUniversalTriggerGuide(records){const target=byId('universal-trigger-list');target.innerHTML=records.length?records.map((entry)=>`<article class="trigger-guide-package"><h4>${safe(entry.package.replace(/^THSV StreamBridge - /u,''))}</h4>${entry.recommendations.length?`<ul>${entry.recommendations.map((recommendation)=>`<li>${safe(recommendation)}</li>`).join('')}</ul>`:'<p>Keep every action in this package triggerless.</p>'}${entry.safety?`<p class="notice"><strong>Safety:</strong> ${safe(entry.safety)}</p>`:''}</article>`).join(''):'<p class="notice">No manual triggers are required for this selection. Keep its actions triggerless.</p>'}
function downloadStreamerBotPackage(filename,contentBase64){const url=URL.createObjectURL(new Blob([contentBase64],{type:'text/plain;charset=us-ascii'}));const link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
byId('select-recommended-imports').addEventListener('click',()=>{for(const input of document.querySelectorAll('#universal-import-packages input[data-import-folder]')){const item=state.universalImports?.packages.find((candidate)=>candidate.folder===input.dataset.importFolder);input.checked=item?.required===true||item?.available===true&&item?.enabled===true}state.lastUniversalImport=null;updateUniversalImportSummary()});
byId('clear-optional-imports').addEventListener('click',()=>{for(const input of document.querySelectorAll('#universal-import-packages input[data-import-folder]:not(:disabled)'))input.checked=false;state.lastUniversalImport=null;updateUniversalImportSummary()});
byId('download-universal-import').addEventListener('click',async()=>{const button=byId('download-universal-import');const status=byId('universal-import-state');button.disabled=true;status.textContent='Building one version-matched Streamer.bot import…';try{const result=await api('/wizard/api/streamerbot/import-package',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({packages:selectedUniversalImportFolders()})});state.lastUniversalImport=result;downloadStreamerBotPackage(result.filename,result.contentBase64);renderUniversalTriggerGuide(result.triggerRecommendations||[]);byId('show-trigger-guide').disabled=false;setGuidedSetupStepComplete('import');status.textContent=`Downloaded ${result.filename}: ${result.actionCount} actions${result.commandCount?` and ${result.commandCount} commands`:''}. Import this one file in Streamer.bot, accept its reviewed C# actions, then follow the trigger checklist below.`}catch(error){status.textContent=`Import was not created: ${error.message}`}finally{button.disabled=false;updateUniversalImportSummary()}});
