async function saveDetectedStreamerBot(executable){const result=await api('/wizard/api/streamerbot-launcher/save',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({executable,approvedByCreator:true})});renderStreamerBotLauncher(result);byId('streamerbot-candidates').innerHTML='';await loadConnectionCenter();showWizardFeedback('Streamer.bot location saved.','success')}
async function detectStreamerBot(){const button=byId('detect-streamerbot');button.disabled=true;showWizardFeedback('Checking safe local locations and running streaming apps…','busy',button);try{const result=await api('/wizard/api/streamerbot-launcher/detect',{method:'POST'});renderStreamerBotLauncher(result.status);const list=byId('streamerbot-candidates');const primary=result.candidates.map((candidate)=>`<article class="item"><span><strong>${safe(candidate.source==='running'?'Running Streamer.bot':candidate.source==='saved'?'Saved Streamer.bot':'Common Streamer.bot location')}</strong><small>${safe(candidate.executable)}</small></span><button type="button" class="ghost" data-use-streamerbot="${safe(candidate.executable)}">Use this</button></article>`);const optional=(result.optionalCandidates||[]).map((candidate)=>`<article class="item"><span><strong>${safe(optionalStreamingAppLabel(candidate.application))} · ${safe(candidate.source)}</strong><small>${safe(candidate.executable)}</small></span><button type="button" class="ghost" data-use-optional="${safe(candidate.application)}" data-optional-path="${safe(candidate.executable)}">Use and enable</button></article>`);list.innerHTML=[...primary,...optional].join('')||'<p class="notice">No apps were found in safe automatic locations. Choose each executable manually.</p>';list.querySelectorAll('[data-use-streamerbot]').forEach((choice)=>choice.addEventListener('click',()=>saveDetectedStreamerBot(choice.dataset.useStreamerbot).catch((error)=>showWizardFeedback(error.message,'error',choice))));list.querySelectorAll('[data-use-optional]').forEach((choice)=>choice.addEventListener('click',()=>saveOptionalStreamingApp(choice.dataset.useOptional,choice.dataset.optionalPath).catch((error)=>showWizardFeedback(error.message,'error',choice))));showWizardFeedback(`Found ${result.candidates.length+(result.optionalCandidates?.length||0)} safe app option(s).`,'success',button)}catch(error){showWizardFeedback(error.message,'error',button)}finally{button.disabled=false}}
async function chooseStreamerBot(){const button=byId('choose-streamerbot');button.disabled=true;showWizardFeedback('Waiting for the Windows file chooser…','busy',button);try{const result=await api('/wizard/api/streamerbot-launcher/choose',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({approvedByCreator:true})});renderStreamerBotLauncher(result);byId('streamerbot-candidates').innerHTML='';await loadConnectionCenter();showWizardFeedback('Streamer.bot location saved.','success',button)}catch(error){showWizardFeedback(error.message,'error',button)}finally{button.disabled=false}}
async function startStreamerBotSafe(button=byId('start-streamerbot-safe')){button.disabled=true;showWizardFeedback('Checking the WebSocket port and starting Streamer.bot safely…','busy',button);try{const result=await runWithStartupProgress(()=>api('/wizard/api/streamerbot-launcher/start',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({approvedByCreator:true})}),button);renderStreamerBotLauncher(result.status);showWizardFeedback(result.output||'Streamer.bot is ready.','success',button)}catch(error){showWizardFeedback(error.message,'error',button)}finally{button.disabled=false;await loadConnectionCenter()}}
async function startAllStreamingTools(button=byId('start-streaming-tools')){button.disabled=true;showWizardFeedback('Starting Streamer.bot, Speaker.bot, StreamBridge, then your enabled broadcast app(s)…','busy',button);try{const result=await runWithStartupProgress(()=>api('/wizard/api/streamerbot-launcher/start-all',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({approvedByCreator:true})}),button);renderStreamerBotLauncher(result.status);const warnings=Array.isArray(result.warnings)?result.warnings:[];showWizardFeedback(warnings.length?`Core tools are ready. Optional app warning: ${warnings.join(' ')}`:result.output||'Your streaming tools are ready.',warnings.length?'warning':'success',button)}catch(error){showWizardFeedback(error.message,'error',button)}finally{button.disabled=false;await loadConnectionCenter()}}
async function createStreamerBotShortcut(){const button=byId('create-streamerbot-shortcut');button.disabled=true;showWizardFeedback('Creating the one-button streaming tools shortcut…','busy',button);try{const result=await api('/wizard/api/streamerbot-launcher/shortcut',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({approvedByCreator:true})});renderStreamerBotLauncher(result.status);showWizardFeedback(`One-button desktop shortcut created at ${result.path}.`,'success',button)}catch(error){showWizardFeedback(error.message,'error',button)}finally{button.disabled=false}}
async function openStreamBridgeFolder(){const button=byId('open-streambridge-folder');button.disabled=true;showWizardFeedback('Opening the installed StreamBridge folder…','busy',button);try{const result=await api('/wizard/api/streamerbot-launcher/open-folder',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({approvedByCreator:true})});showWizardFeedback(`Opened ${result.installRoot}.`,'success',button)}catch(error){showWizardFeedback(error.message,'error',button)}finally{button.disabled=false}}
async function saveOptionalStreamingApp(application,executable){const result=await api('/wizard/api/streamerbot-launcher/optional/save',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({application,executable,enabled:true,approvedByCreator:true})});renderStreamerBotLauncher(result);showWizardFeedback(`${optionalStreamingAppLabel(application)} saved and enabled for one-button startup.`,'success')}
async function chooseOptionalStreamingApp(application){const button=byId(`choose-optional-${application}`);button.disabled=true;showWizardFeedback(`Waiting for the ${optionalStreamingAppLabel(application)} file chooser…`,'busy',button);try{const result=await api('/wizard/api/streamerbot-launcher/optional/choose',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({application,approvedByCreator:true})});renderStreamerBotLauncher(result);showWizardFeedback(`${optionalStreamingAppLabel(application)} saved and enabled.`,'success',button)}catch(error){showWizardFeedback(error.message,'error',button)}finally{button.disabled=false}}
async function toggleOptionalStreamingApp(application,enabled){const toggle=byId(`optional-${application}-enabled`);toggle.disabled=true;try{const result=await api('/wizard/api/streamerbot-launcher/optional/enable',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({application,enabled,approvedByCreator:true})});renderStreamerBotLauncher(result);showWizardFeedback(`${optionalStreamingAppLabel(application)} automatic startup ${enabled?'enabled':'disabled'}.`,'success',toggle)}catch(error){toggle.checked=!enabled;showWizardFeedback(error.message,'error',toggle)}finally{toggle.disabled=false}}
async function copyStreamDeckTarget(){const button=byId('copy-streamdeck-target');const value=byId('streamdeck-launch-target').value;if(!value)return;try{await navigator.clipboard.writeText(value);showWizardFeedback('Stream Deck one-button target copied.','success',button)}catch{byId('streamdeck-launch-target').focus();byId('streamdeck-launch-target').select();showWizardFeedback('Copy the selected Stream Deck target manually.','error',button)}}
async function runInspection(){const button=byId('inspect');const status=byId('inspection-state');button.disabled=true;status.setAttribute('aria-busy','true');status.textContent='Inspecting with GetActions and GetCommands…';try{const result=await inspectStreamerBot();state.lastInspection=result;status.textContent=result.available?`Inspection completed ${new Date(result.inspectedAt).toLocaleString()}. ${result.requests.length} audited read requests.`:`Inspection unavailable: ${result.error}`;items('actions',result.actions,'action');items('commands',result.commands,'command');renderPreStreamReadiness()}catch(error){status.textContent=error.message}finally{status.removeAttribute('aria-busy');button.disabled=false}}
async function authenticateWizard(token){state.token=token.trim();byId('login-error').textContent='';try{state.overview=await api('/wizard/api/overview');renderOverview();byId('login').classList.add('hidden');byId('workspace').classList.remove('hidden');byId('workspace-mode-toggle').classList.remove('hidden');byId('mode').textContent='Authenticated · configuration mode';await recoverConfigurationDraft();applyWorkspaceMode(preferredWorkspaceMode());if(guidedSetupRequested){const cleanUrl=new URL(location.href);cleanUrl.searchParams.delete('guided');history.replaceState(null,'',`${cleanUrl.pathname}${cleanUrl.search}`)}document.dispatchEvent(new CustomEvent('wizard:authenticated'));void runInspection();void loadStreamerBotLauncher();return true}catch(error){state.token='';byId('login-error').textContent=error.message;return false}}
byId('login-form').addEventListener('submit',async(event)=>{event.preventDefault();await authenticateWizard(byId('token').value)});
async function unlockWizardFromLauncher(){const params=new URLSearchParams(location.hash.startsWith('#')?location.hash.slice(1):location.hash);const ticket=params.get('unlock');if(!ticket)return;history.replaceState(null,'',`${location.pathname}${location.search}`);if(!/^[A-Za-z0-9_-]{43}$/u.test(ticket)){byId('login-error').textContent='The automatic unlock link is invalid. Open the setup wizard launcher again.';return}byId('login-error').textContent='Securely unlocking this local wizard…';try{const response=await fetch('/wizard/api/unlock',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({ticket})});const body=await response.json();if(!response.ok||typeof body.controlToken!=='string')throw new Error(body.error||`Unlock failed (${response.status})`);await authenticateWizard(body.controlToken)}catch(error){byId('login-error').textContent=`${error.message} Open the setup wizard launcher again.`}}
