function activatePanel(panelId,{remember=true}={}){const button=document.querySelector(`[data-view="${CSS.escape(panelId)}"]`);const panel=document.querySelector(`[data-panel="${CSS.escape(panelId)}"]`);if(!button||!panel)return false;document.querySelectorAll('[data-view]').forEach((item)=>{const active=item===button;item.classList.toggle('active',active);if(active)item.setAttribute('aria-current','page');else item.removeAttribute('aria-current')});document.querySelectorAll('[data-panel]').forEach((item)=>item.classList.toggle('hidden',item!==panel));if(remember)try{localStorage.setItem(panelStorageKey,panelId)}catch{/* Navigation still works without browser storage. */}panel.querySelector('h2')?.focus?.({preventScroll:true});return true}
