byId('add-filter').addEventListener('submit',async(event)=>{event.preventDefault();const data=new FormData(event.target);const editingId=String(data.get('editingId')||'');const id=editingId||(String(data.get('name')).trim().toLowerCase().replace(/[^a-z0-9-]+/g,'-').replace(/^-+|-+$/g,'').slice(0,50)||`rule-${Date.now()}`);if(!editingId&&state.filters.rules.some((rule)=>rule.id===id)){byId('filter-state').textContent='Use a unique rule name.';return}const scope=String(data.get('scope'));const expiresAtLocal=String(data.get('expiresAt')||'');const rule={id,name:String(data.get('name')).trim(),enabled:data.get('enabled')==='on',scope,moduleIds:scope==='module'?String(data.get('moduleIds')).split(',').map((value)=>value.trim()).filter(Boolean):[],platforms:String(data.get('platforms')).split(',').map((value)=>value.trim().toLowerCase()).filter(Boolean),actorTypes:[],target:String(data.get('target')),match:{kind:String(data.get('kind')),value:String(data.get('value')),caseSensitive:data.get('caseSensitive')==='on'},...(expiresAtLocal?{expiresAt:new Date(expiresAtLocal).toISOString()}:{})};const previousRules=state.filters.rules;state.filters.rules=editingId?state.filters.rules.map((item)=>item.id===editingId?rule:item):[...state.filters.rules,rule];try{await stageFilters();const message=editingId?'Rule updated and staged. Commit the draft to save it.':'Rule staged. Commit the draft to save it.';clearBlockerForm();byId('filter-state').textContent=message}catch(error){state.filters.rules=previousRules;byId('filter-state').textContent=error.message}});
