const previewTokenExamples={actor:'ExampleViewer',amount:'5.00',currency:'USD',quantity:'3',itemName:'Rose',tier:'Tier 1',message:'Thanks for the stream!',metric:'likes',value:'100'};
function fillPreviewTemplate(template,tokens){return template.replace(/\{(\w+)\}/g,(match,key)=>tokens[key]!==undefined&&tokens[key]!==''?tokens[key]:match)}
function buildPreviewMediaNode(videoUrl,imageUrl){if(videoUrl){const video=document.createElement('video');video.src=videoUrl;video.autoplay=true;video.loop=true;video.muted=false;video.playsInline=true;return video}const img=document.createElement('img');img.src=imageUrl;img.alt='';return img}
function renderAlertPreview(){if(!state.selectedAlert)return;const form=byId('alert-profile-form');const {platform,alertType}=state.selectedAlert;const tokens={...previewTokenExamples,alertType:alertTypeLabels[alertType]||alertType,platform};
  const titleTemplate=form.elements.titleTemplate.value||'{actor} sent {amount} {currency}';
  const thankYouTemplate=form.elements.thankYouTemplate.value||alertThankYouTemplates[alertType]||'Thank you, {actor}!';
  const detailTemplate=form.elements.detailTemplate.value||'{message}';
  byId('preview-alert-title').textContent=fillPreviewTemplate(titleTemplate,tokens);
  const thankYou=byId('preview-alert-thank-you');
  thankYou.textContent=fillPreviewTemplate(thankYouTemplate,tokens);
  thankYou.classList.toggle('hidden',!form.elements.showThankYou.checked);
  const viewerMessage=byId('preview-alert-detail');
  viewerMessage.textContent=fillPreviewTemplate(detailTemplate,tokens);
  viewerMessage.classList.toggle('hidden',!form.elements.showViewerMessage.checked);
  const previewPlatform=document.querySelector('.preview-alert-platform');
  previewPlatform.textContent=(platformLabels[platform]||platform).toUpperCase();
  let previewEvent=document.querySelector('.preview-alert-event');
  if(!previewEvent){previewEvent=document.createElement('span');previewEvent.className='preview-alert-event';previewPlatform.insertAdjacentElement('afterend',previewEvent)}
  previewEvent.textContent=(alertTypeLabels[alertType]||alertType).toUpperCase();
  document.querySelector('.preview-alert-avatar').textContent=tokens.actor.charAt(0).toUpperCase();
  const card=byId('alert-preview-card');
  card.dataset.platform=platform;
  card.dataset.alertType=alertType;
  card.style.backgroundColor=form.elements.cardBackgroundColor.value||'#171120';
  const fontMap={system:'"Segoe UI Variable Text","Segoe UI",Arial,sans-serif',rounded:'"Arial Rounded MT Bold","Segoe UI",Arial,sans-serif',serif:'Georgia,"Times New Roman",serif',monospace:'Consolas,"Cascadia Mono",monospace'};
  card.style.fontFamily=fontMap[form.elements.cardFontFamily.value]||fontMap.system;
  const layout=form.elements.cardLayout.value||'classic';
  const videoUrl=form.elements.backgroundVideoUrl.value;
  const imageUrl=form.elements.backgroundImageUrl.value;
  const hasMedia=Boolean(videoUrl||imageUrl);
  const mediaPlacement=hasMedia?(form.elements.cardMediaPlacement.value||'behind'):'behind';
  card.dataset.layout=layout;
  card.dataset.mediaPlacement=mediaPlacement;
  card.dataset.transition=form.elements.cardTransition.value||'slide-vertical';
  const videoWrap=document.querySelector('.preview-alert-video-wrap');
  const previewOverlay=document.querySelector('.preview-alert-video-overlay');
  const insetBox=document.querySelector('.preview-alert-media-inset');
  const bannerBox=document.querySelector('.preview-alert-media-banner');
  const avatarBox=document.querySelector('.preview-alert-avatar');
  videoWrap.innerHTML='';
  insetBox.innerHTML='';
  bannerBox.innerHTML='';
  card.style.removeProperty('background-image');
  previewOverlay.classList.add('hidden');
  insetBox.classList.add('hidden');
  bannerBox.classList.add('hidden');
  const showInsetMedia=hasMedia&&mediaPlacement==='inset';
  avatarBox.classList.toggle('hidden',showInsetMedia||layout==='centered');
  if(hasMedia&&mediaPlacement==='behind'){
    if(videoUrl){videoWrap.append(buildPreviewMediaNode(videoUrl,imageUrl))}
    else{card.style.backgroundImage=`url("${imageUrl.replace(/["\\]/g,'')}")`}
    previewOverlay.classList.remove('hidden');
  }else if(showInsetMedia){
    insetBox.append(buildPreviewMediaNode(videoUrl,imageUrl));
    insetBox.classList.remove('hidden');
  }else if(hasMedia&&mediaPlacement==='below'){
    bannerBox.append(buildPreviewMediaNode(videoUrl,imageUrl));
    bannerBox.classList.remove('hidden');
  }
}
for(const previewField of ['titleTemplate','showThankYou','thankYouTemplate','showViewerMessage','detailTemplate','cardBackgroundColor','cardFontFamily','cardLayout','cardTransition','cardMediaPlacement'])byId('alert-profile-form').elements[previewField].addEventListener('input',renderAlertPreview);
function clearAlertProfile(){state.selectedAlert=null;byId('alert-profile-form').classList.add('hidden');byId('alert-editor-empty').classList.remove('hidden');renderAlertTree()}
async function stageAlerts(){await stageConfigurationChange({kind:'alerts',alertSettings:state.alertSettings});byId('alert-state').textContent='Alert changes staged. Commit and restart StreamBridge to apply them.'}
function readAlertProfile(form){const data=new FormData(form);const aggregationMode=String(data.get('aggregationMode'));const duration=String(data.get('durationMs')||'');const priority=String(data.get('priority')||'');const titleTemplate=String(data.get('titleTemplate')||'').trim();const thankYouTemplate=String(data.get('thankYouTemplate')||'').trim();const detailTemplate=String(data.get('detailTemplate')||'').trim();const customUrl=String(data.get('customSoundUrl')||'');const backgroundImageUrl=String(data.get('backgroundImageUrl')||'');const backgroundVideoUrl=String(data.get('backgroundVideoUrl')||'');return {enabled:data.get('enabled')==='on',...(priority?{priority}:{}),...(duration?{durationMs:Number(duration)}:{}),...(titleTemplate?{titleTemplate}:{}),showThankYou:data.get('showThankYou')==='on',...(thankYouTemplate?{thankYouTemplate}:{}),showViewerMessage:data.get('showViewerMessage')==='on',...(detailTemplate?{detailTemplate}:{}),sound:{mode:String(data.get('soundMode')),volume:Number(data.get('soundVolume')),...(customUrl?{customUrl}:{})},card:{backgroundColor:String(data.get('cardBackgroundColor')),fontFamily:String(data.get('cardFontFamily')),layout:String(data.get('cardLayout')),transition:String(data.get('cardTransition')),mediaPlacement:String(data.get('cardMediaPlacement')),...(backgroundVideoUrl?{backgroundVideoUrl}:backgroundImageUrl?{backgroundImageUrl}:{})},aggregation:{mode:aggregationMode,windowMs:Number(data.get('aggregationWindowMs'))}}}
async function uploadOverlayAsset(file,kind){if(!file)return'';const contentBase64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.addEventListener('load',()=>resolve(String(reader.result).split(',')[1]||''),{once:true});reader.addEventListener('error',()=>reject(new Error('Could not read the selected file.')),{once:true});reader.readAsDataURL(file)});const result=await api('/wizard/api/overlay-assets',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({kind,contentType:file.type,contentBase64})});return result.url}
async function waveDurationMs(file){const bytes=await file.arrayBuffer();const view=new DataView(bytes);const text=(offset,length)=>String.fromCharCode(...new Uint8Array(bytes,offset,length));if(view.byteLength<44||text(0,4)!=='RIFF'||text(8,4)!=='WAVE')throw new Error('Could not read the selected WAV length.');let byteRate=0;let dataSize=0;for(let offset=12;offset+8<=view.byteLength;){const id=text(offset,4);const size=view.getUint32(offset+4,true);const dataOffset=offset+8;if(dataOffset+size>view.byteLength)break;if(id==='fmt '&&size>=16)byteRate=view.getUint32(dataOffset+8,true);if(id==='data'){dataSize=size;break}offset=dataOffset+size+(size%2)}if(byteRate<=0||dataSize<=0)throw new Error('Could not read the selected WAV length.');return Math.ceil(dataSize/byteRate*1000)}
function browserMediaDurationMs(file){return new Promise((resolve,reject)=>{const audio=document.createElement('audio');const objectUrl=URL.createObjectURL(file);const cleanup=()=>{audio.removeEventListener('loadedmetadata',onMetadata);audio.removeEventListener('error',onError);audio.removeAttribute('src');URL.revokeObjectURL(objectUrl)};const onMetadata=()=>{const duration=audio.duration;cleanup();if(!Number.isFinite(duration)||duration<=0){reject(new Error('Could not detect the selected sound length.'));return}resolve(Math.ceil(duration*1000))};const onError=()=>{cleanup();reject(new Error('Could not read the selected sound length.'))};audio.preload='metadata';audio.addEventListener('loadedmetadata',onMetadata,{once:true});audio.addEventListener('error',onError,{once:true});audio.src=objectUrl;audio.load()})}
async function mediaDurationMs(file){if(!file)throw new Error('Choose an audio file first.');return file.type==='audio/wav'||file.name.toLowerCase().endsWith('.wav')?waveDurationMs(file):browserMediaDurationMs(file)}
byId('alert-profile-form').elements.customSoundFile.addEventListener('change',async(event)=>{const file=event.target.files?.[0];try{const trackDurationMs=await mediaDurationMs(file);const url=await uploadOverlayAsset(file,'sound');const form=event.target.form;const paddedDurationMs=Math.min(60000,trackDurationMs+1000);form.elements.customSoundUrl.value=url;form.elements.soundMode.value='custom';form.elements.durationMs.value=String(paddedDurationMs);const capped=trackDurationMs+1000>60000;byId('alert-state').textContent=capped?'Custom sound attached. Its detected length exceeds the 60-second alert limit, so the duration was capped at 60 seconds. Stage and commit the profile to keep it.':`Custom sound attached. Alert duration set to ${(paddedDurationMs/1000).toFixed(1)} seconds (track plus 1 second for entry and exit). Stage and commit the profile to keep it.`}catch(error){event.target.value='';byId('alert-state').textContent=error.message}});
byId('alert-profile-form').elements.backgroundImageFile.addEventListener('change',async(event)=>{try{const url=await uploadOverlayAsset(event.target.files?.[0],'background');const form=event.target.form;form.elements.backgroundImageUrl.value=url;form.elements.backgroundVideoUrl.value='';form.elements.backgroundVideoFile.value='';byId('clear-background-video').classList.add('hidden');byId('alert-state').textContent='Background image attached locally. Stage and commit the profile to keep it.';renderAlertPreview()}catch(error){event.target.value='';byId('alert-state').textContent=error.message}});
byId('alert-profile-form').elements.backgroundVideoFile.addEventListener('change',async(event)=>{try{const url=await uploadOverlayAsset(event.target.files?.[0],'video');const form=event.target.form;form.elements.backgroundVideoUrl.value=url;form.elements.backgroundImageUrl.value='';form.elements.backgroundImageFile.value='';byId('clear-background-video').classList.remove('hidden');byId('alert-state').textContent='Background video attached locally. It will play with its own audio in place of the Sound setting. Stage and commit the profile to keep it.';renderAlertPreview()}catch(error){event.target.value='';byId('alert-state').textContent=error.message}});
byId('clear-background-video').addEventListener('click',()=>{const form=byId('alert-profile-form');form.elements.backgroundVideoUrl.value='';form.elements.backgroundVideoFile.value='';byId('clear-background-video').classList.add('hidden');byId('alert-state').textContent='Background video removed from this form. Stage the profile to keep the change.';renderAlertPreview()});
byId('fire-test-alert').addEventListener('click',async()=>{const form=byId('alert-profile-form');if(!state.selectedAlert||!form.checkValidity()){form.reportValidity();return}const {platform,alertType}=state.selectedAlert;const alerts=structuredClone(state.alertSettings.alerts);alerts.profiles[platform]=alerts.profiles[platform]||{};alerts.profiles[platform][alertType]=readAlertProfile(form);try{const result=await api('/wizard/api/alerts/preview',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({platform,alertType,alerts,alertDurationMs:Number(byId('alert-global-form').elements.alertDurationMs.value)})});byId('alert-state').textContent=result.accepted?`Fired the current unsaved ${platformLabels[platform]} · ${alertTypeLabels[alertType]} design to connected alert overlays.`:'No alert overlay is connected; open the Alerts URL first.'}catch(error){byId('alert-state').textContent=error.message}});
byId('alert-global-form').addEventListener('submit',async(event)=>{event.preventDefault();const data=new FormData(event.target);state.alertSettings.maxAlertQueue=Number(data.get('maxAlertQueue'));state.alertSettings.alertDurationMs=Number(data.get('alertDurationMs'));state.alertSettings.overlayGapMs=Number(data.get('overlayGapMs'));state.alertSettings.showSimulated=data.get('showSimulated')==='on';try{await stageAlerts();renderAlerts()}catch(error){byId('alert-state').textContent=error.message}});
byId('alert-profile-form').addEventListener('submit',async(event)=>{event.preventDefault();const form=event.target;if(!form.checkValidity()||!state.selectedAlert){form.reportValidity();return}const {platform,alertType}=state.selectedAlert;const profile=readAlertProfile(form);if(profile.aggregation.mode==='sum-quantity'&&!['gift','gift-subscription','cheer'].includes(alertType)){byId('alert-state').textContent='Quantity aggregation is available only for gifts, gift subscriptions, and cheers/bits.';return}state.alertSettings.alerts.profiles[platform]=state.alertSettings.alerts.profiles[platform]||{};state.alertSettings.alerts.profiles[platform][alertType]=profile;try{await stageAlerts();selectAlertProfile(platform,alertType);byId('alert-state').textContent='Alert profile staged. Commit and restart StreamBridge to apply it.'}catch(error){byId('alert-state').textContent=error.message}});
byId('reset-alert-profile').addEventListener('click',async()=>{if(!state.selectedAlert)return;const {platform,alertType}=state.selectedAlert;if(!confirm(`Reset ${platformLabels[platform]} · ${alertTypeLabels[alertType]} to its default alert presentation?`))return;if(state.alertSettings.alerts.profiles[platform])delete state.alertSettings.alerts.profiles[platform][alertType];try{await stageAlerts();selectAlertProfile(platform,alertType);byId('alert-state').textContent='Reset to the default alert presentation and staged. Commit and restart StreamBridge to apply it.'}catch(error){byId('alert-state').textContent=error.message;selectAlertProfile(platform,alertType)}});
byId('clear-alert-profile').addEventListener('click',clearAlertProfile);
